import type { Competition, CurrentUserProfile } from '@sport-analytics/contracts';
import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { ApiResponseError } from '../../api/client';
import { CurrentUserContractError, getCurrentUserProfile } from '../auth/current-user-api';
import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import {
  listRequestableCompetitions,
  requestSubmitterAccess,
  SubmitterAccessCompetitionOptionsError,
  SubmitterAccessContractError,
} from './submitter-access-api';

type ProfileState =
  | { kind: 'loading' }
  | { kind: 'error'; message: string }
  | { kind: 'ready'; profile: CurrentUserProfile; competitions: Competition[] };

type Feedback = { kind: 'success' | 'error'; message: string } | null;

function hasSubmissionRole(profile: CurrentUserProfile): boolean {
  return profile.role === 'submitter' || profile.role === 'admin';
}

function canRequestAccess(profile: CurrentUserProfile): boolean {
  return (
    profile.role === 'viewer' &&
    (profile.approvalState === 'not_requested' ||
      profile.approvalState === 'rejected' ||
      profile.approvalState === 'approved')
  );
}

function profileErrorMessage(error: unknown): string {
  if (error instanceof ApiResponseError && error.kind === 'unauthenticated') {
    return 'Your session is no longer valid. Sign in again to check your submitter status.';
  }

  if (error instanceof CurrentUserContractError) {
    return error.message;
  }

  if (error instanceof SubmitterAccessCompetitionOptionsError) {
    return error.message;
  }

  return 'Your submitter status could not be loaded. Please try again.';
}

function requestErrorMessage(error: unknown): string {
  if (error instanceof ApiResponseError && error.kind === 'unauthenticated') {
    return 'Your session is no longer valid. Sign in again before requesting access.';
  }

  if (error instanceof ApiResponseError || error instanceof SubmitterAccessContractError) {
    return error.message;
  }

  return 'Your request could not be submitted. Please try again.';
}

export function SubmitterAccessPanel() {
  const client = useAuthenticatedApiClient();
  const [profileState, setProfileState] = useState<ProfileState>({ kind: 'loading' });
  const [selectedCompetitionId, setSelectedCompetitionId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [feedback, setFeedback] = useState<Feedback>(null);

  const loadProfile = useCallback(
    async (signal?: AbortSignal) => {
      setProfileState({ kind: 'loading' });

      try {
        const profile = await getCurrentUserProfile(client, signal);
        const competitions = canRequestAccess(profile)
          ? await listRequestableCompetitions(signal)
          : [];
        const requestedCompetitionId = profile.requestedCompetition?.competitionId;
        const initialCompetitionId =
          competitions.find((competition) => competition.competitionId === requestedCompetitionId)
            ?.competitionId ??
          competitions[0]?.competitionId ??
          '';

        setSelectedCompetitionId(initialCompetitionId);
        setProfileState({ kind: 'ready', profile, competitions });
      } catch (error) {
        if (signal?.aborted) {
          return;
        }

        setProfileState({ kind: 'error', message: profileErrorMessage(error) });
      }
    },
    [client],
  );

  useEffect(() => {
    const controller = new AbortController();
    void loadProfile(controller.signal);

    return () => controller.abort();
  }, [loadProfile]);

  async function handleRequest(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (profileState.kind !== 'ready' || !selectedCompetitionId) {
      return;
    }

    const existingProfile = profileState.profile;
    const existingCompetitions = profileState.competitions;
    setIsSubmitting(true);
    setFeedback(null);

    try {
      const result = await requestSubmitterAccess(client, selectedCompetitionId);
      setProfileState({
        kind: 'ready',
        profile: {
          ...existingProfile,
          approvalState: 'pending',
          requestedCompetition: result.data.requestedCompetition,
        },
        competitions: existingCompetitions,
      });
      setFeedback({
        kind: 'success',
        message: `Your request for ${result.data.requestedCompetition.name} was submitted and is now awaiting administrator approval.`,
      });

      try {
        const persistedProfile = await getCurrentUserProfile(client);
        setProfileState({
          kind: 'ready',
          profile: persistedProfile,
          competitions: existingCompetitions,
        });
      } catch {
        setFeedback({
          kind: 'success',
          message:
            'Your request was saved, but the latest account profile could not be refreshed. Reload the page to check it again.',
        });
      }
    } catch (error) {
      if (error instanceof ApiResponseError && error.status === 409) {
        try {
          const persistedProfile = await getCurrentUserProfile(client);
          setProfileState({
            kind: 'ready',
            profile: persistedProfile,
            competitions: existingCompetitions,
          });

          if (
            hasSubmissionRole(persistedProfile) ||
            persistedProfile.approvalState === 'pending' ||
            persistedProfile.approvalState === 'approved'
          ) {
            setFeedback({
              kind: 'success',
              message: 'Your submitter status changed and has been refreshed from your account.',
            });
            return;
          }
        } catch {
          // Keep the original, safe conflict response when the latest profile
          // cannot be loaded.
        }
      }

      setFeedback({ kind: 'error', message: requestErrorMessage(error) });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <section className="submitter-access-panel" aria-labelledby="submitter-access-title">
      <div className="submitter-access-panel__heading">
        <div>
          <p className="eyebrow">Cricket event contribution</p>
          <h2 id="submitter-access-title">Submitter access</h2>
        </div>
        {profileState.kind === 'ready' ? (
          <p
            className={`submitter-access-state submitter-access-state--${
              profileState.profile.role === 'viewer'
                ? profileState.profile.approvalState
                : profileState.profile.role
            }`}
          >
            {profileState.profile.role === 'admin'
              ? 'Admin'
              : profileState.profile.role === 'submitter'
                ? 'Submitter'
                : profileState.profile.approvalState === 'not_requested'
                  ? 'Not requested'
                  : profileState.profile.approvalState === 'pending'
                    ? 'Pending approval'
                    : profileState.profile.approvalState === 'approved'
                      ? 'Approved'
                      : 'Not approved'}
          </p>
        ) : null}
      </div>

      {profileState.kind === 'loading' ? (
        <p className="submitter-access-panel__message" role="status">
          Loading your persisted submitter statusâ€¦
        </p>
      ) : profileState.kind === 'error' ? (
        <div className="submitter-access-panel__error" role="alert">
          <p>{profileState.message}</p>
          <button
            className="button button--secondary"
            type="button"
            onClick={() => void loadProfile()}
          >
            Retry status check
          </button>
        </div>
      ) : hasSubmissionRole(profileState.profile) ? (
        <div className="submitter-access-panel__message">
          <p>
            Your account has submission access. Submissions remain limited to the competitions
            assigned by an administrator.
          </p>
          <div className="submitter-access-panel__actions">
            <Link className="button button--primary" to="/submissions/new">
              Submit events
            </Link>
            {profileState.profile.role === 'admin' ? (
              <>
                <Link className="button button--secondary" to="/reviews/batches">
                  Review batches
                </Link>
                <Link className="button button--secondary" to="/admin/users">
                  Manage users
                </Link>
              </>
            ) : null}
          </div>
        </div>
      ) : profileState.profile.approvalState === 'pending' ? (
        <p className="submitter-access-panel__message" role="status">
          Your request
          {profileState.profile.requestedCompetition
            ? ` for ${profileState.profile.requestedCompetition.name}`
            : ''}{' '}
          is awaiting administrator review. You cannot submit another request while this one is
          pending.
        </p>
      ) : (
        <div className="submitter-access-panel__message">
          <p>
            {profileState.profile.approvalState === 'rejected'
              ? 'Your previous request was declined. You can send a new request for review.'
              : profileState.profile.approvalState === 'approved'
                ? 'Your previous submitter access was revoked. You can send a new request for review.'
                : 'Request permission to contribute cricket delivery-event data for one competition. An administrator will review the requested competition scope.'}
          </p>
          {profileState.competitions.length > 0 ? (
            <form
              className="submitter-access-request"
              onSubmit={(event) => void handleRequest(event)}
            >
              <label htmlFor="submitter-access-competition">Competition</label>
              <select
                id="submitter-access-competition"
                value={selectedCompetitionId}
                onChange={(event) => setSelectedCompetitionId(event.target.value)}
                disabled={isSubmitting}
              >
                {profileState.competitions.map((competition) => (
                  <option key={competition.competitionId} value={competition.competitionId}>
                    {competition.name}
                  </option>
                ))}
              </select>
              <p className="field-help">
                Approval grants submission access only within this competition.
              </p>
              <button
                className="button button--primary"
                type="submit"
                disabled={isSubmitting || !selectedCompetitionId}
              >
                {isSubmitting ? 'Requesting accessâ€¦' : 'Request submitter access'}
              </button>
            </form>
          ) : (
            <p className="submitter-access-panel__empty" role="status">
              No competitions are currently available for an access request.
            </p>
          )}
        </div>
      )}

      {feedback ? (
        <p
          className={
            feedback.kind === 'error'
              ? 'submitter-access-feedback submitter-access-feedback--error'
              : 'submitter-access-feedback'
          }
          role={feedback.kind === 'error' ? 'alert' : 'status'}
        >
          {feedback.message}
        </p>
      ) : null}
    </section>
  );
}
import type { ApplicationRole, SubmitterApprovalState } from '@sport-analytics/contracts';
import type { AuthChangeEvent, Session, User } from '@supabase/supabase-js';
import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { PublicApp } from '../../App';
import { AuthProvider } from '../auth/AuthProvider';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];
type AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;

function jsonResponse(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function createSession(): Session {
  const user = {
    id: 'requesting-user',
    aud: 'authenticated',
    role: 'authenticated',
    email: 'viewer@example.com',
    app_metadata: {},
    user_metadata: {},
    identities: [],
    created_at: '2026-08-16T00:00:00.000Z',
  } satisfies User;

  return {
    access_token: 'viewer-access-token',
    refresh_token: 'managed-by-supabase',
    expires_in: 3600,
    token_type: 'bearer',
    user,
  };
}

function createAuthClient(session: Session | null = createSession()) {
  return {
    getSession: vi.fn().mockResolvedValue({ data: { session } }),
    onAuthStateChange: vi.fn((listener: AuthStateListener) => ({
      data: {
        subscription: {
          id: 'submitter-access-test-subscription',
          callback: listener,
          unsubscribe: vi.fn(),
        },
      },
    })),
    signInWithOAuth: vi
      .fn()
      .mockResolvedValue({ data: { provider: 'google', url: null }, error: null }),
    signOut: vi.fn().mockResolvedValue({ error: null }),
  } as unknown as AuthClient;
}

function currentUser(
  approvalState: SubmitterApprovalState,
  role: ApplicationRole = 'viewer',
  requestedCompetition = approvalState === 'not_requested'
    ? null
    : { competitionId: '5', name: 'Premier T20' },
): Response {
  return jsonResponse(200, {
    user: {
      id: '17',
      subject: 'requesting-user',
      displayName: 'Requesting User',
      role,
      approvalState,
      requestedCompetition,
      competitionIds: role === 'submitter' || role === 'admin' ? ['5'] : [],
    },
  });
}

function competitionsResponse(
  competitions = [
    { competitionId: '5', name: 'Premier T20' },
    { competitionId: '8', name: 'University League' },
  ],
): Response {
  return jsonResponse(200, {
    data: competitions,
    pagination: { nextCursor: null },
  });
}

function renderAccountPage(session: Session | null = createSession()) {
  return render(
    <AuthProvider client={createAuthClient(session)}>
      <MemoryRouter initialEntries={['/account']}>
        <PublicApp />
      </MemoryRouter>
    </AuthProvider>,
  );
}

function useSystemTheme() {
  vi.stubGlobal(
    'matchMedia',
    vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  );
}

describe('submitter access request and status interface', () => {
  beforeEach(() => {
    window.localStorage.clear();
    useSystemTheme();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('does not load application account data while signed out', async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage(null);

    expect(await screen.findByText(/you are signed out/i)).toBeInTheDocument();
    expect(screen.queryByRole('heading', { name: 'Submitter access' })).not.toBeInTheDocument();
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it('submits an eligible request, exposes progress, and reloads the persisted pending state', async () => {
    let approvalState: SubmitterApprovalState = 'not_requested';
    let requestedCompetition: { competitionId: string; name: string } | null = null;
    let resolveRequest!: (response: Response) => void;
    const pendingRequest = new Promise<Response>((resolve) => {
      resolveRequest = resolve;
    });
    const fetchMock = vi.fn().mockImplementation((input: RequestInfo | URL) => {
      const path = new URL(String(input)).pathname;

      if (path.endsWith('/auth/me')) {
        return Promise.resolve(currentUser(approvalState, 'viewer', requestedCompetition));
      }

      if (path.endsWith('/competitions')) {
        return Promise.resolve(competitionsResponse());
      }

      if (path.endsWith('/submitter-access-requests')) {
        return pendingRequest;
      }

      throw new Error(`Unexpected request: ${path}`);
    });
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage();

    const competitionSelect = await screen.findByRole('combobox', { name: 'Competition' });
    expect(competitionSelect).toHaveValue('5');
    fireEvent.change(competitionSelect, { target: { value: '8' } });
    fireEvent.click(await screen.findByRole('button', { name: 'Request submitter access' }));

    expect(screen.getByRole('button', { name: 'Requesting accessâ€¦' })).toBeDisabled();

    approvalState = 'pending';
    requestedCompetition = { competitionId: '8', name: 'University League' };
    await act(async () => {
      resolveRequest(
        jsonResponse(201, {
          data: {
            accountId: '17',
            approvalState: 'pending',
            requestedCompetition: { competitionId: '8', name: 'University League' },
          },
        }),
      );
    });

    expect(await screen.findByText('Pending approval')).toBeInTheDocument();
    expect(
      screen.getByText(
        'Your request for University League was submitted and is now awaiting administrator approval.',
      ),
    ).toHaveAttribute('role', 'status');
    expect(screen.queryByRole('button', { name: /request submitter access/i })).toBeNull();

    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(4));
    const requestCall = fetchMock.mock.calls.find(([input]) =>
      new URL(String(input)).pathname.endsWith('/submitter-access-requests'),
    ) as [string, RequestInit];
    const [, requestInit] = requestCall;
    expect(requestInit.method).toBe('POST');
    expect(requestInit.body).toBe(JSON.stringify({ competitionId: '8' }));
    expect(new Headers(requestInit.headers).get('Authorization')).toBe(
      'Bearer viewer-access-token',
    );
  });

  it('restores a persisted pending state after remount without offering another request', async () => {
    const fetchMock = vi.fn().mockResolvedValue(currentUser('pending'));
    vi.stubGlobal('fetch', fetchMock);

    const firstRender = renderAccountPage();
    expect(await screen.findByText('Pending approval')).toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /request submitter access/i })).toBeNull();

    firstRender.unmount();
    renderAccountPage();

    expect(await screen.findByText('Pending approval')).toBeInTheDocument();
    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(screen.queryByRole('button', { name: /request submitter access/i })).toBeNull();
  });

  it('shows an empty state when no competitions are available to request', async () => {
    vi.stubGlobal(
      'fetch',
      vi
        .fn()
        .mockResolvedValueOnce(currentUser('not_requested'))
        .mockResolvedValueOnce(competitionsResponse([])),
    );

    renderAccountPage();

    expect(
      await screen.findByText('No competitions are currently available for an access request.'),
    ).toHaveAttribute('role', 'status');
    expect(screen.queryByRole('combobox', { name: 'Competition' })).not.toBeInTheDocument();
    expect(
      screen.queryByRole('button', { name: 'Request submitter access' }),
    ).not.toBeInTheDocument();
  });

  it('refreshes a stale eligible view when the backend reports an active request conflict', async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(currentUser('not_requested'))
      .mockResolvedValueOnce(competitionsResponse())
      .mockResolvedValueOnce(
        jsonResponse(409, {
          error: {
            code: 'REQUEST_ALREADY_PENDING',
            message: 'A submitter access request is already pending.',
          },
        }),
      )
      .mockResolvedValueOnce(currentUser('pending'));
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage();

    fireEvent.click(await screen.findByRole('button', { name: 'Request submitter access' }));

    expect(await screen.findByText('Pending approval')).toBeInTheDocument();
    expect(
      screen.getByText('Your submitter status changed and has been refreshed from your account.'),
    ).toHaveAttribute('role', 'status');
    expect(screen.queryByRole('button', { name: /request submitter access/i })).toBeNull();
  });

  it('shows submitter access from the role without a request action', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(currentUser('approved', 'submitter')));

    renderAccountPage();

    expect(await screen.findByText('Submitter')).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Submit events' })).toHaveAttribute(
      'href',
      '/submissions/new',
    );
    expect(screen.queryByRole('link', { name: 'Upload a batch' })).toBeNull();
    expect(screen.queryByRole('button', { name: /request submitter access/i })).toBeNull();
  });

  it('exposes submission access to an admin regardless of legacy approval state', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(currentUser('not_requested', 'admin')));

    renderAccountPage();

    expect(await screen.findByText('Admin')).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Submit events' })).toHaveAttribute(
      'href',
      '/submissions/new',
    );
  });

  it('permits a revoked viewer to request access again without restoring submission access', async () => {
    vi.stubGlobal(
      'fetch',
      vi
        .fn()
        .mockResolvedValueOnce(currentUser('approved'))
        .mockResolvedValueOnce(competitionsResponse()),
    );

    renderAccountPage();

    expect(await screen.findByText(/previous submitter access was revoked/i)).toBeInTheDocument();
    expect(screen.queryByRole('link', { name: 'Submit events' })).toBeNull();
    expect(screen.getByRole('button', { name: 'Request submitter access' })).toBeEnabled();
  });

  it('explains rejected access and permits a new request', async () => {
    vi.stubGlobal(
      'fetch',
      vi
        .fn()
        .mockResolvedValueOnce(currentUser('rejected'))
        .mockResolvedValueOnce(competitionsResponse()),
    );

    renderAccountPage();

    expect(await screen.findByText('Not approved')).toBeInTheDocument();
    expect(screen.getByText(/previous request was declined/i)).toBeInTheDocument();
    expect(screen.getByRole('combobox', { name: 'Competition' })).toHaveValue('5');
    expect(screen.getByRole('button', { name: 'Request submitter access' })).toBeEnabled();
  });

  it('reports an unauthenticated status response as an expired session', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        jsonResponse(401, {
          error: {
            code: 'UNAUTHORIZED',
            message: 'A valid authentication token is required.',
          },
        }),
      ),
    );

    renderAccountPage();

    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Your session is no longer valid. Sign in again to check your submitter status.',
    );
  });

  it('retries a server-error status response and renders the resolved access state', async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(
        jsonResponse(500, {
          error: {
            code: 'INTERNAL_SERVER_ERROR',
            message: 'The server could not complete the request.',
          },
        }),
      )
      .mockResolvedValueOnce(currentUser('approved', 'submitter'));
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage();

    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Your submitter status could not be loaded. Please try again.',
    );
    fireEvent.click(screen.getByRole('button', { name: 'Retry status check' }));

    expect(await screen.findByText('Submitter')).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Submit events' })).toHaveAttribute(
      'href',
      '/submissions/new',
    );
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('communicates profile and request failures and leaves retry available', async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(
        jsonResponse(200, {
          user: { approvalState: 'not_requested' },
        }),
      )
      .mockResolvedValueOnce(currentUser('not_requested'))
      .mockResolvedValueOnce(competitionsResponse())
      .mockResolvedValueOnce(
        jsonResponse(503, {
          error: {
            code: 'SERVICE_UNAVAILABLE',
            message: 'Submitter access requests are temporarily unavailable.',
          },
        }),
      );
    vi.stubGlobal('fetch', fetchMock);

    renderAccountPage();

    expect(await screen.findByRole('alert')).toHaveTextContent(
      'The API returned an unexpected account response. Please try again.',
    );
    fireEvent.click(screen.getByRole('button', { name: 'Retry status check' }));
    fireEvent.click(await screen.findByRole('button', { name: 'Request submitter access' }));

    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Submitter access requests are temporarily unavailable.',
    );
    expect(screen.getByRole('button', { name: 'Request submitter access' })).toBeEnabled();
  });
});

