import { useMemo } from 'react';
import { createAuthenticatedApiClient, type AuthenticatedApiClient } from '../../api/client';
import { useAuth } from './AuthProvider';

export function useAuthenticatedApiClient(): AuthenticatedApiClient {
  const { session } = useAuth();

  return useMemo(
    () => createAuthenticatedApiClient(() => session?.access_token ?? null),
    [session?.access_token],
  );
}
import type { Session, SupabaseClient, User } from '@supabase/supabase-js';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';

type SupabaseAuthClient = Pick<
  SupabaseClient['auth'],
  'getSession' | 'onAuthStateChange' | 'signInWithOAuth' | 'signOut'
>;

export interface AuthState {
  isLoading: boolean;
  isAuthenticated: boolean;
  session: Session | null;
  identity: User | null;
}

interface AuthContextValue extends AuthState {
  signInWithGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
  clearLocalSession: () => Promise<void>;
}

interface AuthProviderProps {
  children: ReactNode;
  client: SupabaseAuthClient;
}

const initialAuthState: AuthState = {
  isLoading: true,
  isAuthenticated: false,
  session: null,
  identity: null,
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

function resolveAuthState(session: Session | null): AuthState {
  return {
    isLoading: false,
    isAuthenticated: session !== null,
    session,
    identity: session?.user ?? null,
  };
}

export function AuthProvider({ children, client }: AuthProviderProps) {
  const [authState, setAuthState] = useState<AuthState>(initialAuthState);

  useEffect(() => {
    let isActive = true;
    let receivedAuthEvent = false;
    const initialSession = client.getSession();
    const {
      data: { subscription },
    } = client.onAuthStateChange((_event, session) => {
      receivedAuthEvent = true;

      if (isActive) {
        setAuthState(resolveAuthState(session));
      }
    });

    void initialSession
      .then(({ data }) => {
        if (isActive && !receivedAuthEvent) {
          setAuthState(resolveAuthState(data.session));
        }
      })
      .catch(() => {
        if (isActive && !receivedAuthEvent) {
          setAuthState(resolveAuthState(null));
        }
      });

    return () => {
      isActive = false;
      subscription.unsubscribe();
    };
  }, [client]);

  const signInWithGoogle = useCallback(async () => {
    const { error } = await client.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: `${window.location.origin}/auth/callback`,
      },
    });

    if (error) {
      throw new Error('Google authentication could not be started.');
    }
  }, [client]);

  const signOut = useCallback(async () => {
    const { error } = await client.signOut();

    if (error) {
      throw new Error('Sign-out could not be completed.');
    }
  }, [client]);

  const clearLocalSession = useCallback(async () => {
    const { error } = await client.signOut({ scope: 'local' });

    // A deleted application account must leave the managed React session even
    // if the now-removed Auth identity makes Supabase return an error.
    setAuthState(resolveAuthState(null));

    if (error) {
      throw new Error('Local session cleanup could not be confirmed.');
    }
  }, [client]);

  const value = useMemo(
    () => ({ ...authState, signInWithGoogle, signOut, clearLocalSession }),
    [authState, clearLocalSession, signInWithGoogle, signOut],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const authState = useContext(AuthContext);

  if (!authState) {
    throw new Error('useAuth must be used within an AuthProvider');
  }

  return authState;
}
import {
  currentUserProfileResponseSchema,
  type CurrentUserProfile,
} from '@sport-analytics/contracts';
import type { AuthenticatedApiClient } from '../../api/client';

export class CurrentUserContractError extends Error {
  constructor() {
    super('The API returned an unexpected account response. Please try again.');
    this.name = 'CurrentUserContractError';
  }
}

export async function getCurrentUserProfile(
  client: AuthenticatedApiClient,
  signal?: AbortSignal,
): Promise<CurrentUserProfile> {
  const response = await client.request<unknown>('/auth/me', signal ? { signal } : {});
  const parsed = currentUserProfileResponseSchema.safeParse(response);

  if (!parsed.success) {
    throw new CurrentUserContractError();
  }

  return parsed.data.user;
}
import { apiErrorResponseSchema, type ApiErrorDetail } from '@sport-analytics/contracts';

const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:3000/api/v1';

export type ApiErrorKind = 'unauthenticated' | 'forbidden' | 'request-failed';

export class ApiResponseError extends Error {
  readonly kind: ApiErrorKind;
  readonly status: number;
  readonly code: string | undefined;
  readonly details: ApiErrorDetail[] | undefined;

  constructor(
    status: number,
    message = `API request failed with status ${status}`,
    options: {
      code?: string | undefined;
      details?: ApiErrorDetail[] | undefined;
    } = {},
  ) {
    const kind =
      status === 401 ? 'unauthenticated' : status === 403 ? 'forbidden' : 'request-failed';

    super(message);
    this.name = 'ApiResponseError';
    this.kind = kind;
    this.status = status;
    this.code = options.code;
    this.details = options.details;
  }
}

export type AccessTokenProvider = () => string | null;

export interface AuthenticatedApiClient {
  request<ResponseBody>(path: string, init?: RequestInit): Promise<ResponseBody>;
}

export function createAuthenticatedApiClient(
  getAccessToken: AccessTokenProvider,
): AuthenticatedApiClient {
  return {
    async request<ResponseBody>(path: string, init: RequestInit = {}): Promise<ResponseBody> {
      const headers = new Headers(init.headers);
      const accessToken = getAccessToken();

      if (!headers.has('Accept')) {
        headers.set('Accept', 'application/json');
      }

      if (accessToken) {
        headers.set('Authorization', `Bearer ${accessToken}`);
      } else {
        headers.delete('Authorization');
      }

      const normalizedPath = path.startsWith('/') ? path : `/${path}`;
      const response = await fetch(`${apiBaseUrl}${normalizedPath}`, {
        ...init,
        headers,
      });

      if (!response.ok) {
        let body: unknown = null;

        try {
          body = await response.json();
        } catch {
          // Some infrastructure failures have no JSON body. The status-based
          // fallback below still gives the interface a safe error state.
        }

        const errorResponse = apiErrorResponseSchema.safeParse(body);

        if (errorResponse.success) {
          throw new ApiResponseError(response.status, errorResponse.data.error.message, {
            code: errorResponse.data.error.code,
            details: errorResponse.data.error.details,
          });
        }

        throw new ApiResponseError(response.status);
      }

      if (response.status === 204) {
        return undefined as ResponseBody;
      }

      return (await response.json()) as ResponseBody;
    },
  };
}
