import { spawnSync } from 'node:child_process';

const workspaces = {
  frontend: '@sport-analytics/frontend',
  backend: '@sport-analytics/backend',
};

const argumentsToForward = process.argv.slice(2);
const requestedApp = argumentsToForward[0]?.startsWith('-')
  ? 'frontend'
  : (argumentsToForward.shift() ?? 'frontend');

if (!(requestedApp in workspaces)) {
  console.error(`Unknown development app "${requestedApp}". Use "frontend" or "backend".`);
  process.exitCode = 1;
} else {
  const npmCli = process.env.npm_execpath;

  if (!npmCli) {
    console.error('npm_execpath is unavailable. Start this command through npm.');
    process.exitCode = 1;
  } else {
    const result = spawnSync(
      process.execPath,
      [
        npmCli,
        'run',
        'dev',
        `--workspace=${workspaces[requestedApp]}`,
        '--',
        ...argumentsToForward,
      ],
      { stdio: 'inherit' },
    );

    if (result.error) {
      console.error(`Could not start the ${requestedApp} development app: ${result.error.message}`);
      process.exitCode = 1;
    } else {
      process.exitCode = result.status ?? 1;
    }
  }
}
import 'dotenv/config';

import { createApp } from './app';
import { loadEnvironment } from './config/env';
import { closeDatabasePool } from './database';

const environment = loadEnvironment();
const app = createApp({ environment });

const server = app.listen(environment.PORT, () => {
  console.log(`Sport Analytics API listening on port ${environment.PORT}`);
});

let shuttingDown = false;

function closeHttpServer(): Promise<void> {
  return new Promise((resolve, reject) => {
    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}

async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) {
    return;
  }

  shuttingDown = true;

  console.log(`${signal} received; shutting down`);

  try {
    await closeHttpServer();
  } catch {
    console.error('Failed to close HTTP server cleanly.');
    process.exitCode = 1;
  }

  try {
    await closeDatabasePool();
  } catch {
    console.error('Failed to close database pool cleanly.');
    process.exitCode = 1;
  }
}

process.on('SIGINT', () => {
  void shutdown('SIGINT');
});

process.on('SIGTERM', () => {
  void shutdown('SIGTERM');
});
import { z } from 'zod';

const optionalNonEmptyString = z.preprocess(
  (value) => (typeof value === 'string' && value.trim() === '' ? undefined : value),
  z.string().trim().min(1).optional(),
);

const environmentSchema = z
  .object({
    NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
    PORT: z.coerce.number().int().positive().max(65_535).default(3000),
    CORS_ORIGINS: z.string().default('http://localhost:5173'),
    SUPABASE_URL: z.string().trim().url('Supabase URL must be a valid URL'),
    SUPABASE_PUBLISHABLE_KEY: z.string().trim().min(1, 'Supabase publishable key is required'),
    SUPABASE_SECRET_KEY: optionalNonEmptyString,
    AZURE_STORAGE_ACCOUNT_NAME: optionalNonEmptyString.pipe(
      z
        .string()
        .regex(
          /^[a-z0-9]{3,24}$/,
          'Azure storage account name must be 3-24 lowercase letters or numbers',
        )
        .optional(),
    ),
    AZURE_STORAGE_CONTAINER_NAME: optionalNonEmptyString.pipe(
      z
        .string()
        .regex(
          /^(?!.*--)[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])$/,
          'Azure storage container name must be 3-63 lowercase letters, numbers or single hyphens',
        )
        .optional(),
    ),
  })
  .superRefine((environment, context) => {
    if (environment.NODE_ENV !== 'production') {
      return;
    }

    if (!environment.AZURE_STORAGE_ACCOUNT_NAME) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['AZURE_STORAGE_ACCOUNT_NAME'],
        message: 'Azure storage account name is required in production',
      });
    }

    if (!environment.AZURE_STORAGE_CONTAINER_NAME) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['AZURE_STORAGE_CONTAINER_NAME'],
        message: 'Azure storage container name is required in production',
      });
    }
  });

export type Environment = z.infer<typeof environmentSchema>;

export function loadEnvironment(source: NodeJS.ProcessEnv = process.env): Environment {
  const result = environmentSchema.safeParse(source);

  if (!result.success) {
    const details = result.error.issues
      .map((issue) => `${issue.path.join('.') || 'environment'}: ${issue.message}`)
      .join('; ');

    throw new Error(`Invalid environment configuration: ${details}`);
  }

  return result.data;
}
